#include <string.h>

int main(void) {
    char M[300];
    if (fgets(M, sizeof(M), stdin) == NULL) return 0;

    int divertido = 0, chateado = 0;
    size_t n = strlen(M);

    for (size_t i = 0; i + 2 < n; i++) {
        if (M[i] == ':' && M[i + 1] == '-') {
            if (M[i + 2] == ')') {
                divertido++;
            } else if (M[i + 2] == '(') {
                chateado++;
            }
        }
    }

    if (divertido > chateado) {
        printf("divertido\n");
    } else if (chateado > divertido) {
        printf("chateado\n");
    } else {
        printf("neutro\n");
    }

    return 0;
}
